class MyClass {
    String f;
    int lineNumber;

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null) return false;
        if (getClass() != obj.getClass()) return false;
        MyClass other = (MyClass) obj;

        if (f == null) {
            if (other.f != null)
                return false;
        } else if (!f.equals(other.f))
            return false;

        if (lineNumber != other.lineNumber)
            return false;
        return true;
    }
}

